"""Tests for plr.py: python3 -m unittest img-config/plr/test_plr.py

Set PLR_TEST_GCODE to a sliced file to also run the simulated power cuts on
it.
"""

import math
import os
import random
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import plr  # noqa: E402

SAMPLE = """\
; generated by test
PRINT_START BED_TEMP=60 EXTRUDER_TEMP=210
G90
M83
SET_RETRACTION RETRACT_LENGTH=0.8 RETRACT_SPEED=40 UNRETRACT_EXTRA_LENGTH=0 UNRETRACT_SPEED=30
EXCLUDE_OBJECT_DEFINE NAME=cube CENTER=100,100 POLYGON=[[90,90],[110,90],[110,110],[90,110]]
M106 S0
;LAYER_CHANGE
;Z:0.2
G10 ; retract
G1 X90 Y90 F12000
G1 Z.2
G11 ; unretract
EXCLUDE_OBJECT_START NAME=cube
G1 F1800
G1 X110 Y90 E1.0
G1 X110 Y110 E1.0
G3 X90 Y110 I-10 J0 E1.2
G1 X90 Y90 E1.0
EXCLUDE_OBJECT_END NAME=cube
;LAYER_CHANGE
;Z:0.4
M106 S128
G10 ; retract
G1 X90 Y90 Z.4 F12000
G11 ; unretract
EXCLUDE_OBJECT_START NAME=cube
G1 F1500
G1 X110 Y90 E1.0
G1 X110 Y110 E1.0
G1 X90 Y110 E1.0
G1 X90 Y90 E1.0
G1 X110 Y90 E1.0
G1 X110 Y110 E1.0
EXCLUDE_OBJECT_END NAME=cube
PRINT_END
"""


def point_on(m, t):
    if m.arc:
        cx, cy, r, a0, sweep = m.arc
        a = a0 + sweep * t
        return cx + r * math.cos(a), cy + r * math.sin(a), m.z0 + (m.z1 - m.z0) * t
    return (m.x0 + (m.x1 - m.x0) * t, m.y0 + (m.y1 - m.y0) * t, m.z0 + (m.z1 - m.z0) * t)


def make_checkpoint(path, fp, move, t, extrude_factor=1.0, homing=(0.0, 0.0, 0.05)):
    """Checkpoint as Klipper would report it with the toolhead on a move.

    The file is read up to and including the line at fp, and the toolhead is
    placed at fraction t of a move: the one on the line at byte offset move,
    or for a negative number, that many moves back from the end.
    """
    model = plr.GcodeModel(0.8, 0.0)
    for offset, text in plr.iter_lines(path):
        if offset > fp:
            break
        model.feed(text, offset)
    moves = list(model.moves)
    m = moves[move] if move < 0 else next(m for m in moves if m.offset == move)
    x, y, z = point_on(m, t)
    live_e = m.e0 + (m.e1 - m.e0) * t
    gpos = model.pos + [model.e]
    toolhead_e = 500 + model.cum_e * extrude_factor
    pos = [gpos[i] + homing[i] for i in range(3)] + [toolhead_e]
    live = [x + homing[0], y + homing[1], z + homing[2] + 0.07,
            toolhead_e - (model.cum_e - live_e) * extrude_factor]
    status = {
        "print_stats": {"state": "printing", "filename": "sub/test.gcode"},
        "virtual_sdcard": {"is_active": True, "file_position": fp},
        "motion_report": {"live_position": live},
        "toolhead": {"position": pos, "axis_minimum": [-2, -2, -5, 0],
                     "axis_maximum": [430, 430, 505, 0], "max_velocity": 250,
                     "max_accel": 3000, "square_corner_velocity": 5},
        "gcode_move": {"gcode_position": gpos, "position": pos,
                       "homing_origin": list(homing) + [0.0],
                       "extrude_factor": extrude_factor, "speed_factor": 1.0},
        "extruder": {"target": 215, "pressure_advance": 0.03, "smooth_time": 0.04},
        "heater_bed": {"target": 60},
        "fan": {"speed": 0.5},
        "firmware_retraction": {"retract_length": 0.8, "retract_speed": 40,
                                "unretract_extra_length": 0, "unretract_speed": 30},
        "bed_mesh": {"profile_name": "default", "profiles": {"default": {
            "points": [[0.1, 0.2], [0.0, -0.1]],
            "mesh_params": {"min_x": 10.0, "max_x": 397.0, "min_y": 21.0, "max_y": 404.0,
                            "x_count": 2, "y_count": 2, "mesh_x_pps": 2, "mesh_y_pps": 2,
                            "algo": "lagrange", "tension": 0.2}}}},
        "exclude_object": {"excluded_objects": []},
    }
    cp = {"version": 1, "id": 1234, "time": 0, "state": "printing",
          "filename": "sub/test.gcode", "file_path": path, "file_position": fp,
          "status": status}
    return cp, m


class SampleTest(unittest.TestCase):
    def setUp(self):
        fd, self.path = tempfile.mkstemp(suffix=".gcode")
        with os.fdopen(fd, "w") as f:
            f.write(SAMPLE)
        self.offsets = {text: off for off, text in plr.iter_lines(self.path)}

    def tearDown(self):
        os.remove(self.path)

    def test_split_command(self):
        self.assertEqual(plr.split_command("G1 X1.5 y-2 E.3 ; c")[:2],
                         ("G1", {"X": "1.5", "Y": "-2", "E": ".3"}))
        self.assertEqual(plr.split_command("G01X1")[:2], ("G1", {"X": "1"}))
        self.assertEqual(plr.split_command("SET_VELOCITY_LIMIT ACCEL=500")[:2],
                         ("SET_VELOCITY_LIMIT", {"ACCEL": "500"}))
        self.assertEqual(plr.split_command(";Z:0.4"), (None, None, "Z:0.4"))

    def test_resumes_from_start_of_current_line(self):
        # Toolhead halfway along the arc, the file read 7 moves further
        arc = self.offsets["G3 X90 Y110 I-10 J0 E1.2"]
        cp, m = make_checkpoint(self.path, self.offsets["G1 X110 Y110 E1.0"], arc, 0.5)
        p = plr.plan(cp, self.path)
        self.assertEqual(p["resume_offset"], arc)
        self.assertEqual(p["method"], "position+extruder")
        s = p["state"]
        self.assertEqual(s.pos, [110.0, 110.0, 0.2])
        self.assertEqual(s.obj, "cube")
        self.assertEqual(s.layer, 1)
        self.assertEqual(s.f, 1800.0)
        self.assertFalse(s.fw_retracted)

    def test_layer_boundary_and_retraction_state(self):
        # Toolhead on the travel to layer 2, after the G10
        travel = self.offsets["G1 X90 Y90 Z.4 F12000"]
        cp, m = make_checkpoint(self.path, self.offsets["G1 X110 Y110 E1.0"], travel, 0.0)
        p = plr.plan(cp, self.path)
        self.assertEqual(p["resume_offset"], travel)
        s = p["state"]
        self.assertTrue(s.fw_retracted)
        self.assertEqual(s.obj, None)
        g = plr.resume_gcode(p)
        # purge retract undone, then retracted again the way the file expects
        self.assertEqual(g[g.index("G1 Z0.2 F600") + 1:g.index("G1 Z0.2 F600") + 3],
                         ["G1 E0.8 F2400", "G10"])
        self.assertIn("M106 S128", g)
        self.assertEqual(g[-3:], ["M26 S%d" % travel, "M117 Printing", "M24"])

    def test_end_of_move_resumes_next_line(self):
        cp, m = make_checkpoint(self.path, self.offsets["G1 X90 Y90 E1.0"],
                                self.offsets["G3 X90 Y110 I-10 J0 E1.2"], 1.0)
        p = plr.plan(cp, self.path)
        # The line is finished, so the next move is the one to print again
        first = next(o for o, text in plr.iter_lines(self.path) if text == "G1 X90 Y90 E1.0")
        self.assertEqual(p["resume_offset"], first)
        self.assertGreater(p["resume_offset"], m.offset)

    def test_extrude_factor(self):
        cp, m = make_checkpoint(self.path, self.offsets["G1 X110 Y110 E1.0"], -3, 0.3,
                                extrude_factor=0.9)
        p = plr.plan(cp, self.path)
        self.assertEqual(p["resume_offset"], m.offset)

    def test_unknown_position(self):
        cp, m = make_checkpoint(self.path, self.offsets["G1 F1500"], -2, 0.5)
        cp["status"]["motion_report"]["live_position"][0] += 50
        with self.assertRaises(plr.PlanError):
            plr.plan(cp, self.path)

    def test_paused(self):
        fp = self.offsets["M106 S128"]
        cp, m = make_checkpoint(self.path, fp, -1, 1.0)
        cp["state"] = "paused"
        p = plr.plan(cp, self.path)
        self.assertEqual(p["resume_offset"], fp)

    def test_cfg(self):
        cp, m = make_checkpoint(self.path, self.offsets["G1 F1500"],
                                self.offsets["G3 X90 Y110 I-10 J0 E1.2"], 0.5)
        p = plr.plan(cp, self.path)
        text, error = plr.build_cfg(cp, p, "/tmp/variables.cfg")
        self.assertIsNone(error)
        self.assertIn("[bed_mesh plr]", text)
        self.assertIn("M23 sub/test.gcode", text)
        self.assertIn("EXCLUDE_OBJECT_START NAME=cube", text)
        for line in text.splitlines():
            if not line.startswith("#"):
                self.assertNotIn("#", line)

    def test_cfg_error(self):
        cp, m = make_checkpoint(self.path, self.offsets["G1 F1500"],
                                self.offsets["G3 X90 Y110 I-10 J0 E1.2"], 0.5)
        text, error = plr.build_cfg(cp, plr.PlanError("broken"), "/tmp/v.cfg")
        self.assertEqual(error, "broken")
        self.assertIn("Can't resume: broken", text)
        self.assertNotIn("M24", text)


class RealFileTest(unittest.TestCase):
    """Simulated power cuts at random places in a real file."""

    @unittest.skipUnless(os.environ.get("PLR_TEST_GCODE"), "PLR_TEST_GCODE not set")
    def test_random_cuts(self):
        path = os.environ["PLR_TEST_GCODE"]
        offsets = [o for o, _ in plr.iter_lines(path)]
        rng = random.Random(4)
        for _ in range(int(os.environ.get("PLR_TEST_CUTS", "10"))):
            fp = rng.choice(offsets[len(offsets) // 50:-200])
            back = rng.randint(0, 300)
            t = rng.choice([0.0, 0.5, rng.random()])
            cp, m = make_checkpoint(path, fp, -1 - back, t)
            p = plr.plan(cp, path)
            self.assertEqual(p["resume_offset"], m.offset, (fp, back, t))
            # The faster second pass must give the same state as reading from
            # the start of the file
            full = plr.GcodeModel(0.8, 0.0, window=1)
            for offset, text in plr.iter_lines(path, stop=p["resume_offset"]):
                full.feed(text, offset)
            s = p["state"]
            self.assertAlmostEqual(s.e, full.e, places=6)
            for attr in ("pos", "f", "abs_e", "fw_retracted", "slicer_retract", "layer",
                         "obj", "state_lines", "velocity", "defines", "line"):
                self.assertEqual(getattr(s, attr), getattr(full, attr), attr)


if __name__ == "__main__":
    unittest.main()
